package com.metrics.hub.controller;

import com.metrics.hub.dto.LayoutDto;
import com.metrics.hub.entity.DashboardLayout;
import com.metrics.hub.mapper.LayoutMapper;
import com.metrics.hub.repository.DashboardLayoutRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/dashboards")
public class DashboardLayoutController {

    private final DashboardLayoutRepository layoutRepository;
    private final LayoutMapper layoutMapper;

    public DashboardLayoutController(DashboardLayoutRepository layoutRepository, LayoutMapper layoutMapper) {
        this.layoutRepository = layoutRepository;
        this.layoutMapper = layoutMapper;
    }

    @PutMapping("/{dashboardId}/layout")
    public ResponseEntity<String> updateLayout(
            @PathVariable Long dashboardId,
            @RequestBody LayoutDto layoutDto,
            Authentication authentication) {
        DashboardLayout layout = layoutRepository.findById(dashboardId)
                .orElseThrow(() -> new IllegalArgumentException("Dashboard not found"));
        if (!layout.getCreatorUsername().equals(authentication.getName())) {
            throw new AccessDeniedException("Cannot modify dashboard layout belonging to another creator");
        }
        layoutMapper.updateEntity(layoutDto, layout);
        layoutRepository.save(layout);
        return ResponseEntity.ok("Layout updated");
    }
}
